class Solution {
public:
    long long findScore(vector<int>& nums) {
        int n = nums.size();
        vector<int> idx(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            if (nums[a] != nums[b]) return nums[a] < nums[b];
            return a < b;
        });
        vector<char> marked(n, 0);
        long long score = 0;
        for (int i : idx) {
            if (marked[i]) continue;
            score += nums[i];
            marked[i] = 1;
            if (i > 0) marked[i - 1] = 1;
            if (i < n - 1) marked[i + 1] = 1;
        }
        return score;
    }
};
